From 9395e562f6e079cdcf2404738e1822f82441f0a5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:58:22 +0100
Subject: [PATCH] logout-greeter: expose how much data is still waiting to be
 written

After a big copy to a slow drive finishes, shutting down can sit at the
console for a long time while the kernel flushes it, with no warning in
Plasma. Read the pending amount and keep it updated for the logout screen.

BUG: 454367
---
 logout-greeter/shutdowndlg.cpp | 30 ++++++++++++++++++++++++++++++
 1 file changed, 30 insertions(+)

diff --git a/logout-greeter/shutdowndlg.cpp b/logout-greeter/shutdowndlg.cpp
index ce552d3ca0..a3e3e81919 100644
--- a/logout-greeter/shutdowndlg.cpp
+++ b/logout-greeter/shutdowndlg.cpp
@@ -54,6 +54,22 @@ QFileInfo systemdUpdateTriggerFileInfo()
     }
     return {};
 }
+
+// Data the kernel still has to write to disk, which shutting down or restarting has to wait for
+qulonglong unwrittenDataSize()
+{
+    QFile meminfo(u"/proc/meminfo"_s);
+    if (!meminfo.open(QIODevice::ReadOnly)) {
+        return 0;
+    }
+    qulonglong kib = 0;
+    for (const QByteArray &line : meminfo.readAll().split('\n')) {
+        if (line.startsWith("Dirty:") || line.startsWith("Writeback:")) {
+            kib += line.mid(line.indexOf(':') + 1).simplified().split(' ').constFirst().toULongLong();
+        }
+    }
+    return kib * 1024;
+}
 } // namespace

 static const QString s_login1Service = QStringLiteral("org.freedesktop.login1");
@@ -196,6 +212,20 @@ KSMShutdownDlg::KSMShutdownDlg(QQmlEngine *engine, ShutdownType sdtype, bool win

     context->setContextProperty(u"softwareUpdatePending"_s, updateTriggered() || upgradeTriggered());

+    // Small amounts are written within a moment, so only report enough data to noticeably delay shutting down
+    auto updateUnwrittenDataSize = [context] {
+        const qulonglong size = unwrittenDataSize();
+        const QVariant value = size >= 64 * 1024 * 1024 ? size : 0;
+        if (context->contextProperty(u"unwrittenDataSize"_s) != value) {
+            context->setContextProperty(u"unwrittenDataSize"_s, value);
+        }
+    };
+    updateUnwrittenDataSize();
+    auto *unwrittenDataTimer = new QTimer(this);
+    unwrittenDataTimer->setInterval(1000);
+    connect(unwrittenDataTimer, &QTimer::timeout, context, updateUnwrittenDataSize);
+    unwrittenDataTimer->start();
+
     // TODO KF6 remove, used to read "BootManager" from kdmrc
     context->setContextProperty(QStringLiteral("bootManager"), QStringLiteral("None"));

